import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import {
  ArrowLeft,
  Save,
  Plus,
  Trash2,
  Clock,
  Layout,
  Layers,
  Info,
  X,
  Loader2,
  AlertCircle,
  CheckCircle2,
  Video,
} from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { shopApi } from '../api/shop';
import { CourseModule, CourseLesson } from '../types';

type EditorTab = 'details' | 'curriculum' | 'settings';

const CourseEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { shopConfig, refreshAll } = useShop();

  const isEditing = Boolean(id);
  const activeCurrency = shopConfig.currency || 'IRR';

  const [activeTab, setActiveTab] = useState<EditorTab>('details');
  const [loading, setLoading] = useState(isEditing);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  // Course Details
  const [title, setTitle] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [slug, setSlug] = useState('');
  const [sku, setSku] = useState('');
  const [price, setPrice] = useState('');
  const [originalPrice, setOriginalPrice] = useState('');
  const [thumbnail, setThumbnail] = useState('');
  const [description, setDescription] = useState('');

  // Curriculum
  const [modules, setModules] = useState<CourseModule[]>([]);

  // Settings
  const [level, setLevel] = useState<'beginner' | 'intermediate' | 'advanced' | 'expert'>('intermediate');
  const [category, setCategory] = useState('engineering');
  const [domain, setDomain] = useState('fintech');
  const [visibility, setVisibility] = useState<'hidden' | 'catalog' | 'search' | 'featured'>('catalog');
  const [instructorId, setInstructorId] = useState('');
  const [seatAllocation, setSeatAllocation] = useState('');
  const [tagsText, setTagsText] = useState('');
  const [featuresText, setFeaturesText] = useState('');

  useEffect(() => {
    if (!id) return;
    let mounted = true;
    const loadCourse = async () => {
      setLoading(true);
      setError(null);
      try {
        const [courseMeta, fullContent] = await Promise.all([
          shopApi.getCourse(id),
          shopApi.getCourseContent(id).catch(() => null),
        ]);
        if (!mounted) return;
        if (!courseMeta) {
          setError('Course not found.');
          return;
        }
        setTitle(courseMeta.title || '');
        setSubtitle(courseMeta.subtitle || '');
        setSlug(courseMeta.slug || '');
        setSku(courseMeta.sku || '');
        setPrice(courseMeta.price ? String(courseMeta.price) : '');
        setOriginalPrice(courseMeta.originalPrice ? String(courseMeta.originalPrice) : '');
        setThumbnail(courseMeta.image || '');
        setDescription(courseMeta.description || '');
        setLevel((courseMeta.level as any) || 'intermediate');
        setCategory(courseMeta.category || 'engineering');
        setDomain(courseMeta.domain || 'fintech');
        setVisibility(courseMeta.visibility || 'catalog');
        setSeatAllocation(courseMeta.seatAllocation || '');
        setTagsText((courseMeta.tags || []).join(', '));
        setFeaturesText((courseMeta.features || []).join('\n'));

        const loadedModules = fullContent?.content || courseMeta.content || [];
        setModules(
          Array.isArray(loadedModules)
            ? loadedModules.map((m: any, mIdx: number) => ({
                id: m.id || `m_${mIdx + 1}`,
                title: m.title || m.moduleName || `Module ${mIdx + 1}`,
                order: m.order ?? mIdx + 1,
                lessons: Array.isArray(m.lessons)
                  ? m.lessons.map((l: any, lIdx: number) => ({
                      id: l.id || `l_${mIdx + 1}_${lIdx + 1}`,
                      title: l.title || l.lessonName || `Lesson ${lIdx + 1}`,
                      duration: String(l.duration ?? '05:00'),
                      videoUrl: l.videoUrl || '',
                      isPreviewFree: Boolean(l.isPreviewFree),
                      order: l.order ?? lIdx + 1,
                    }))
                  : [],
              }))
            : []
        );
      } catch (err: any) {
        if (mounted) setError(err?.error || err?.message || 'Failed to load course details.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    loadCourse();
    return () => {
      mounted = false;
    };
  }, [id]);

  const addModule = () => {
    setModules(prev => [
      ...prev,
      {
        id: `m_${Date.now()}`,
        title: `Module ${prev.length + 1}`,
        order: prev.length + 1,
        lessons: [
          {
            id: `l_${Date.now()}_1`,
            title: 'Introduction Lesson',
            duration: '05:00',
            videoUrl: '',
            isPreviewFree: prev.length === 0,
            order: 1,
          },
        ],
      },
    ]);
  };

  const updateModule = (moduleId: string, nextTitle: string) => {
    setModules(prev => prev.map(m => (m.id === moduleId ? { ...m, title: nextTitle } : m)));
  };

  const deleteModule = (moduleId: string) => {
    setModules(prev => prev.filter(m => m.id !== moduleId));
  };

  const addLesson = (moduleId: string) => {
    setModules(prev =>
      prev.map(m =>
        m.id === moduleId
          ? {
              ...m,
              lessons: [
                ...m.lessons,
                {
                  id: `l_${Date.now()}`,
                  title: `Lesson ${m.lessons.length + 1}`,
                  duration: '05:00',
                  videoUrl: '',
                  isPreviewFree: false,
                  order: m.lessons.length + 1,
                },
              ],
            }
          : m
      )
    );
  };

  const updateLesson = (
    moduleId: string,
    lessonId: string,
    field: keyof CourseLesson,
    value: any
  ) => {
    setModules(prev =>
      prev.map(m =>
        m.id === moduleId
          ? {
              ...m,
              lessons: m.lessons.map(l => (l.id === lessonId ? { ...l, [field]: value } : l)),
            }
          : m
      )
    );
  };

  const deleteLesson = (moduleId: string, lessonId: string) => {
    setModules(prev =>
      prev.map(m =>
        m.id === moduleId
          ? { ...m, lessons: m.lessons.filter(l => l.id !== lessonId) }
          : m
      )
    );
  };

  const handleSave = async () => {
    setError(null);
    setNotice(null);

    const parsedPrice = Math.round(Number(price));
    if (!title.trim() || title.trim().length < 5 || title.trim().length > 200) {
      setError('Course title must be between 5 and 200 characters.');
      setActiveTab('details');
      return;
    }
    if (!description.trim() || description.trim().length < 10 || description.trim().length > 5000) {
      setError('Description must be between 10 and 5,000 characters.');
      setActiveTab('details');
      return;
    }
    if (!Number.isInteger(parsedPrice) || parsedPrice <= 0) {
      setError(`Course price must be a positive integer in ${activeCurrency}.`);
      setActiveTab('details');
      return;
    }
    if (modules.length === 0) {
      setError('Add at least one curriculum module before saving.');
      setActiveTab('curriculum');
      return;
    }
    if (modules.some(m => !m.lessons || m.lessons.length === 0)) {
      setError('Every curriculum module must contain at least one lesson.');
      setActiveTab('curriculum');
      return;
    }

    const sanitizedContent = modules.map((m, mIdx) => ({
      id: m.id,
      title: m.title.trim() || `Module ${mIdx + 1}`,
      order: mIdx + 1,
      lessons: m.lessons.map((l, lIdx) => {
        const entry: Record<string, any> = {
          id: l.id,
          title: l.title.trim() || `Lesson ${lIdx + 1}`,
          duration: l.duration.trim() || '05:00',
          isPreviewFree: Boolean(l.isPreviewFree),
          order: lIdx + 1,
        };
        if (l.videoUrl && l.videoUrl.trim()) {
          entry.videoUrl = l.videoUrl.trim();
        }
        return entry;
      }),
    }));

    const payload: Record<string, any> = {
      title: title.trim(),
      description: description.trim(),
      price: parsedPrice,
      currency: activeCurrency,
      level,
      category: category.trim() || 'other',
      domain,
      visibility,
      content: sanitizedContent,
    };

    if (subtitle.trim()) payload.subtitle = subtitle.trim();
    if (slug.trim()) payload.slug = slug.trim().toLowerCase();
    if (sku.trim()) payload.sku = sku.trim();
    if (seatAllocation.trim()) payload.seatAllocation = seatAllocation.trim();
    if (instructorId.trim()) payload.instructor = instructorId.trim();
    if (thumbnail.trim()) {
      payload.thumbnail = thumbnail.trim();
      payload.image = thumbnail.trim();
    }
    if (originalPrice.trim()) {
      const parsedOrig = Math.round(Number(originalPrice));
      if (!Number.isInteger(parsedOrig) || parsedOrig < parsedPrice) {
        setError('Original price must be an integer >= price.');
        return;
      }
      payload.originalPrice = parsedOrig;
    }
    const tags = tagsText.split(',').map(s => s.trim()).filter(Boolean);
    if (tags.length > 0) payload.tags = tags;
    const features = featuresText.split('\n').map(s => s.trim()).filter(Boolean);
    if (features.length > 0) payload.features = features;

    setSubmitting(true);
    try {
      if (isEditing && id) {
        await shopApi.updateCourse(id, payload);
        setNotice('Course updated successfully.');
        await refreshAll();
      } else {
        const res = await shopApi.createCourse(payload);
        const createdId = res?.course?._id || res?.course?.id;
        await refreshAll();
        if (createdId) {
          navigate(`/admin/course/edit/${createdId}`, { replace: true });
          return;
        }
        navigate('/creator/catalog');
      }
    } catch (err: any) {
      const details = Array.isArray(err?.details) && err.details.length > 0
        ? err.details.map((d: any) => `${d.field || 'field'}: ${d.message}`).join('; ')
        : null;
      setError(details || err?.error || err?.message || 'Failed to save course.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-28 flex items-center justify-center text-slate-500">
        <Loader2 className="animate-spin text-emerald-600 mr-2" size={20} /> Loading course...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pb-20 pt-16">
      <header className="bg-white/90 dark:bg-[#101216]/90 backdrop-blur-md border-b border-[#E4E4DE] dark:border-[#222630] sticky top-16 z-40">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => navigate('/creator/catalog')}
              className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors text-slate-500"
            >
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white truncate">
              {isEditing ? 'Edit Course' : 'Create Course'}
            </h1>
          </div>
          <button
            type="button"
            disabled={submitting}
            onClick={handleSave}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-semibold text-xs md:text-sm hover:bg-emerald-500 transition-colors flex items-center gap-2 disabled:opacity-50"
          >
            {submitting ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
            <span>{isEditing ? 'Save Course' : 'Create Draft'}</span>
          </button>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 pt-6">
        {error && (
          <div className="mb-4 p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
            <AlertCircle size={15} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}
        {notice && (
          <div className="mb-4 p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
            <CheckCircle2 size={15} className="shrink-0" />
            <span>{notice}</span>
          </div>
        )}
      </div>

      <div className="max-w-7xl mx-auto px-4 py-4 flex flex-col lg:flex-row gap-8">
        <aside className="lg:w-60 shrink-0">
          <div className="flex lg:flex-col overflow-x-auto pb-2 lg:pb-0 gap-2">
            {[
              { id: 'details', label: 'Details', icon: Info },
              { id: 'curriculum', label: 'Curriculum', icon: Layers },
              { id: 'settings', label: 'Settings', icon: Layout },
            ].map(tab => (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id as EditorTab)}
                className={`flex items-center gap-2.5 px-4 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-colors whitespace-nowrap border ${
                  activeTab === tab.id
                    ? 'bg-emerald-600 text-white border-emerald-500'
                    : 'bg-white dark:bg-[#111318] text-slate-600 dark:text-slate-400 border-[#E4E4DE] dark:border-[#222630]'
                }`}
              >
                <tab.icon size={16} />
                <span>{tab.label}</span>
              </button>
            ))}
          </div>
        </aside>

        <div className="flex-1 min-w-0">
          {activeTab === 'details' && (
            <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-5">
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Course Title * (5–200 chars)
                </label>
                <input
                  type="text"
                  minLength={5}
                  maxLength={200}
                  value={title}
                  onChange={e => setTitle(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-base font-bold text-slate-900 dark:text-white"
                  placeholder="e.g. Institutional MQL5 & Market Microstructure"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Price ({activeCurrency}) *
                  </label>
                  <input
                    type="number"
                    min={1}
                    step={1}
                    value={price}
                    onChange={e => setPrice(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono tabular-nums text-slate-900 dark:text-white"
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Original Price ({activeCurrency})
                  </label>
                  <input
                    type="number"
                    min={1}
                    step={1}
                    value={originalPrice}
                    onChange={e => setOriginalPrice(e.target.value)}
                    placeholder="Optional"
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono tabular-nums text-slate-900 dark:text-white"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Thumbnail Image URI
                </label>
                <input
                  type="url"
                  value={thumbnail}
                  onChange={e => setThumbnail(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
                  placeholder="https://..."
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                  Description * (10–5,000 chars)
                </label>
                <textarea
                  rows={5}
                  value={description}
                  onChange={e => setDescription(e.target.value)}
                  className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                />
              </div>
            </div>
          )}

          {activeTab === 'curriculum' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <div>
                  <h2 className="text-lg font-bold text-slate-900 dark:text-white">
                    Curriculum Builder
                  </h2>
                  <p className="text-xs text-slate-500">
                    Lessons support external videoUrl links and isPreviewFree gating.
                  </p>
                </div>
                <button
                  type="button"
                  onClick={addModule}
                  className="px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-950 rounded-lg font-bold text-xs inline-flex items-center gap-1.5"
                >
                  <Plus size={14} /> Add Module
                </button>
              </div>

              {modules.length === 0 ? (
                <div className="p-10 text-center bg-white dark:bg-[#111318] rounded-2xl border border-[#E4E4DE] dark:border-[#222630] text-xs text-slate-500">
                  No modules yet. Add your first module to define lessons.
                </div>
              ) : (
                <div className="space-y-4">
                  {modules.map((mod, mIdx) => (
                    <div
                      key={mod.id}
                      className="bg-white dark:bg-[#111318] rounded-2xl border border-[#E4E4DE] dark:border-[#222630] overflow-hidden"
                    >
                      <div className="bg-[#F3F3EE] dark:bg-[#171A21] p-4 flex items-center gap-3 border-b border-[#E4E4DE] dark:border-[#222630]">
                        <span className="text-xs font-mono font-bold text-slate-400">
                          M{mIdx + 1}
                        </span>
                        <input
                          type="text"
                          value={mod.title}
                          onChange={e => updateModule(mod.id, e.target.value)}
                          className="bg-transparent border-none outline-none font-bold text-slate-900 dark:text-white flex-1 text-sm"
                        />
                        <button
                          type="button"
                          onClick={() => deleteModule(mod.id)}
                          className="text-slate-400 hover:text-rose-500 p-1.5"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>

                      <div className="p-4 space-y-3">
                        {mod.lessons.map((lesson, lIdx) => (
                          <div
                            key={lesson.id}
                            className="p-3.5 rounded-xl bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] space-y-2.5"
                          >
                            <div className="flex flex-col sm:flex-row sm:items-center gap-2.5">
                              <span className="text-xs font-mono font-bold text-slate-400">
                                {lIdx + 1}.
                              </span>
                              <input
                                type="text"
                                value={lesson.title}
                                onChange={e => updateLesson(mod.id, lesson.id, 'title', e.target.value)}
                                className="flex-1 bg-white dark:bg-[#111318] px-3 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] text-xs font-semibold text-slate-900 dark:text-white"
                                placeholder="Lesson Title"
                              />
                              <div className="relative w-28">
                                <Clock size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input
                                  type="text"
                                  value={lesson.duration}
                                  onChange={e => updateLesson(mod.id, lesson.id, 'duration', e.target.value)}
                                  className="w-full bg-white dark:bg-[#111318] pl-7 pr-2 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] text-xs font-mono text-slate-900 dark:text-white"
                                  placeholder="12:30"
                                />
                              </div>
                              <button
                                type="button"
                                onClick={() => deleteLesson(mod.id, lesson.id)}
                                className="p-1.5 text-slate-400 hover:text-rose-500 self-end sm:self-auto"
                              >
                                <X size={15} />
                              </button>
                            </div>

                            <div className="flex flex-col sm:flex-row sm:items-center gap-3 pl-4">
                              <div className="relative flex-1">
                                <Video size={12} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input
                                  type="url"
                                  value={lesson.videoUrl || ''}
                                  onChange={e => updateLesson(mod.id, lesson.id, 'videoUrl', e.target.value)}
                                  placeholder="Lesson videoUrl (https://...)"
                                  className="w-full bg-white dark:bg-[#111318] pl-8 pr-3 py-1.5 rounded-lg border border-[#E4E4DE] dark:border-[#222630] text-xs font-mono text-slate-900 dark:text-white"
                                />
                              </div>
                              <label className="flex items-center gap-1.5 text-xs text-slate-600 dark:text-slate-300 whitespace-nowrap">
                                <input
                                  type="checkbox"
                                  checked={Boolean(lesson.isPreviewFree)}
                                  onChange={e =>
                                    updateLesson(mod.id, lesson.id, 'isPreviewFree', e.target.checked)
                                  }
                                  className="accent-emerald-600"
                                />
                                <span>Free Preview</span>
                              </label>
                            </div>
                          </div>
                        ))}

                        <button
                          type="button"
                          onClick={() => addLesson(mod.id)}
                          className="w-full py-2 border border-dashed border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-bold text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/5 inline-flex items-center justify-center gap-1"
                        >
                          <Plus size={14} /> Add Lesson
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-5">
              <h2 className="text-xs font-mono font-bold uppercase tracking-wider text-slate-500">
                Course Classification &amp; Publishing Settings
              </h2>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Difficulty Level
                  </label>
                  <select
                    value={level}
                    onChange={e => setLevel(e.target.value as any)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  >
                    <option value="beginner">beginner</option>
                    <option value="intermediate">intermediate</option>
                    <option value="advanced">advanced</option>
                    <option value="expert">expert</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Category
                  </label>
                  <input
                    type="text"
                    value={category}
                    onChange={e => setCategory(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Domain
                  </label>
                  <select
                    value={domain}
                    onChange={e => setDomain(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  >
                    <option value="fintech">fintech</option>
                    <option value="saas">saas</option>
                    <option value="commerce">commerce</option>
                    <option value="frontend">frontend</option>
                    <option value="software">software</option>
                    <option value="other">other</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Visibility
                  </label>
                  <select
                    value={visibility}
                    onChange={e => setVisibility(e.target.value as any)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  >
                    <option value="catalog">catalog</option>
                    <option value="search">search</option>
                    <option value="featured">featured</option>
                    <option value="hidden">hidden</option>
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Subtitle
                  </label>
                  <input
                    type="text"
                    maxLength={240}
                    value={subtitle}
                    onChange={e => setSubtitle(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    URL Slug
                  </label>
                  <input
                    type="text"
                    value={slug}
                    onChange={e => setSlug(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    SKU
                  </label>
                  <input
                    type="text"
                    value={sku}
                    onChange={e => setSku(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Instructor User ID (optional MongoDB ID)
                  </label>
                  <input
                    type="text"
                    value={instructorId}
                    onChange={e => setInstructorId(e.target.value)}
                    placeholder="Defaults to current user"
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm font-mono text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Seat Allocation
                  </label>
                  <input
                    type="text"
                    value={seatAllocation}
                    onChange={e => setSeatAllocation(e.target.value)}
                    placeholder="e.g. Individual Seat"
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Tags (comma separated)
                  </label>
                  <input
                    type="text"
                    value={tagsText}
                    onChange={e => setTagsText(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  />
                </div>

                <div className="sm:col-span-2">
                  <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">
                    Curriculum Highlights / Features (one per line)
                  </label>
                  <textarea
                    rows={3}
                    value={featuresText}
                    onChange={e => setFeaturesText(e.target.value)}
                    className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
                  />
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CourseEditor;
